import * as THREE from './three.module.js';
const stops=[
{name:'Evolution',sub:'Pra começar com adrenalina',region:'Wild West · Adrenalina',copy:'Começar lá em cima! Nossa primeira parada para entrar no clima do parque.',x:.698,y:.500},
{name:'Brinquedos aquáticos',sub:'Splash + Rio Bravo',region:'Wild West · Água',copy:'Primeiro Splash, depois Rio Bravo. Separe essa parte do dia para se molhar e se divertir!',x:.815,y:.426,extra:{x:.666,y:.632}},
{name:'Almoço',sub:'Pausa para recarregar',region:'Pausa · Local a combinar',copy:'Hora de almoçar e recuperar as energias. O restaurante será escolhido pelo grupo; o ponto no mapa é apenas uma sugestão de encontro.',x:.763,y:.551},
{name:'Katapul',sub:'O looping',region:'Aribabiba / Liga da Justiça · Adrenalina',copy:'Depois do almoço, partiu Katapul! Respeite o tempo de descanso que você precisar.',x:.591,y:.158},
{name:'Chapéu mexicano',sub:'Um giro mais leve',region:'Aribabiba / Liga da Justiça · Chapéu mexicano',copy:'É a vez do chapéu mexicano: os balanços suspensos do Trukes di Pinguim.',x:.594,y:.245},
{name:'Vurang',sub:'Montanha-russa no escuro',region:'Mistieri · No escuro',copy:'Entrar no escuro e deixar a surpresa por conta das curvas do Vurang.',x:.232,y:.263},
{name:'Uma pausa ou mais emoção',sub:'Brinquedos de boa / Montezum',region:'Tempo livre · Você escolhe',copy:'Espaço para brinquedos mais de boa. Se a fila estiver pequena, vale uma rodada extra na Montezum! O ponto indica essa alternativa.',x:.160,y:.630},
{name:'Ekatomb',sub:'De volta à adrenalina',region:'Mistieri · Adrenalina',copy:'A turma se encontra de novo para encarar o Ekatomb.',x:.243,y:.380},
{name:'Barco viking',sub:'Já no comecinho da noite',region:'Mistieri · Viland Viking',copy:'Balançar no barco viking quando já estiver começando a escurecer.',x:.288,y:.342},
{name:'Montezum',sub:'A última montanha-russa',region:'Mistieri · Grande final',copy:'Montezum para fechar os brinquedos! A expectativa do grupo é encontrar menos fila nesse horário, mas isso pode variar.',x:.121,y:.507},
{name:'Hora do Horror',sub:'Livres para curtir a noite',region:'Noite · Monstros e labirintos',copy:'Todo mundo livre para curtir os monstros e labirintos! Confira a programação e os locais no dia; não há um ponto único indicado no mapa.',x:null,y:null}
];
const $=s=>document.querySelector(s),nav=$('#itinerary');let selected=0,scene,renderer,camera,root,route,pinData=[],yaw=0,tilt=.48,zoom=1,drag=null,view3=true;
stops.forEach((s,i)=>{const b=document.createElement('button');b.className='stop';b.innerHTML=`<span class="stop-num">${String(i+1).padStart(2,'0')}</span><span class="stop-text"><strong>${s.name}</strong><small>${s.sub}</small></span><span class="arrow">↗</span>`;b.onclick=()=>{select(i);if(matchMedia("(max-width:760px)").matches)document.querySelector(".map-panel").scrollIntoView({behavior:"smooth"})};nav.append(b)});
function select(i){selected=i;[...nav.children].forEach((b,j)=>{b.classList.toggle('active',i===j);b.setAttribute('aria-current',i===j?'step':'false')});const s=stops[i];$('#detail-number').textContent=String(i+1).padStart(2,'0');$('#detail-region').textContent=s.region.toUpperCase();$('#detail-title').textContent=s.name;$('#detail-copy').textContent=s.copy;$('#next').textContent=i===10?'↺':'↗';$('#next').setAttribute('aria-label',i===10?'Voltar à primeira parada':'Ir para próxima parada');pinData.forEach(p=>{p.button.classList.toggle('active',p.index===i);p.button.setAttribute('aria-pressed',String(p.index===i));p.mesh.material.color.set(p.index===i?0xd4f777:0x244e36)});}
$('#next').onclick=()=>select((selected+1)%stops.length);
function setView(v){view3=v;tilt=v?.48:0;yaw=0;$('#view3').classList.toggle('active',v);$('#view2').classList.toggle('active',!v);$('#view3').setAttribute('aria-pressed',String(v));$('#view2').setAttribute('aria-pressed',String(!v));}
$('#view3').onclick=()=>setView(true);$('#view2').onclick=()=>setView(false);$('#plus').onclick=()=>zoom=Math.min(2.7,zoom*1.18);$('#minus').onclick=()=>zoom=Math.max(.65,zoom/1.18);$('#reset').onclick=()=>{zoom=1;setView(true)};
const viewport=$('#viewport');const position=(x,y,h=.04)=>new THREE.Vector3((x-.5)*18,h,(y-.5)*10.24);
try{
renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.outputColorSpace=THREE.SRGBColorSpace;viewport.prepend(renderer.domElement);scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(38,1,.1,100);camera.position.set(0,17,0);camera.up.set(0,0,-1);camera.lookAt(0,0,0);root=new THREE.Group();scene.add(root);
scene.add(new THREE.HemisphereLight(0xffffff,0x637654,2.1));const sun=new THREE.DirectionalLight(0xffffff,2);sun.position.set(-8,15,7);scene.add(sun);
const slab=new THREE.Mesh(new THREE.BoxGeometry(18,.2,10.24),new THREE.MeshStandardMaterial({color:0x608247,roughness:1}));slab.position.y=-.11;root.add(slab);
const tex=await new THREE.TextureLoader().loadAsync('./mapa.png');tex.colorSpace=THREE.SRGBColorSpace;tex.repeat.set(1,1012/1408);tex.offset.set(0,1-1012/1408);tex.anisotropy=renderer.capabilities.getMaxAnisotropy();const surface=new THREE.Mesh(new THREE.PlaneGeometry(18,10.24),new THREE.MeshBasicMaterial({map:tex}));surface.rotation.x=-Math.PI/2;root.add(surface);
function addPin(s,i,extra=false){const b=document.createElement('button');b.className='pin'+(extra?' secondary':'');b.textContent=extra?'2b':i+1;b.title=extra?'2 · Rio Bravo':`${i+1} · ${s.name}`;b.setAttribute('aria-label',b.title);b.onclick=e=>{e.stopPropagation();select(i)};$('#pins').append(b);const p=position(s.x,s.y,.02);const mesh=new THREE.Mesh(new THREE.CylinderGeometry(.028,.045,.42,8),new THREE.MeshStandardMaterial({color:0x244e36}));mesh.position.copy(p);mesh.position.y=.23;root.add(mesh);pinData.push({button:b,index:i,mesh,point:position(s.x,s.y,.55)})}
stops.forEach((s,i)=>{if(s.x!==null)addPin(s,i);if(s.extra)addPin({...s,...s.extra},i,true)});
const points=[];stops.forEach(s=>{if(s.x!==null)points.push(position(s.x,s.y,.07));if(s.extra)points.push(position(s.extra.x,s.extra.y,.07))});route=new THREE.Line(new THREE.BufferGeometry().setFromPoints(points),new THREE.LineDashedMaterial({color:0xd9fa81,dashSize:.13,gapSize:.09,transparent:true,opacity:.95}));route.computeLineDistances();root.add(route);
function resize(){const w=viewport.clientWidth,h=viewport.clientHeight;renderer.setSize(w,h);camera.aspect=w/h;camera.updateProjectionMatrix()}new ResizeObserver(resize).observe(viewport);resize();
const projected=new THREE.Vector3();function animate(){requestAnimationFrame(animate);const fit=Math.max(19,10/camera.aspect/Math.tan(THREE.MathUtils.degToRad(19)));camera.position.y=fit/zoom;camera.updateMatrixWorld();root.rotation.x=tilt;root.rotation.y=yaw;root.updateMatrixWorld();renderer.render(scene,camera);pinData.forEach(p=>{projected.copy(p.point);root.localToWorld(projected);projected.project(camera);p.button.style.left=((projected.x+1)/2*viewport.clientWidth)+'px';p.button.style.top=((-projected.y+1)/2*viewport.clientHeight)+'px';p.button.style.display=(Math.abs(projected.x)>1.1||Math.abs(projected.y)>1.1)?'none':''})}animate();
viewport.addEventListener('pointerdown',e=>{if(e.target.closest('button'))return;drag={x:e.clientX,y:e.clientY,yaw,tilt};viewport.setPointerCapture(e.pointerId)});viewport.addEventListener('pointermove',e=>{if(!drag)return;yaw=drag.yaw+(e.clientX-drag.x)*.004;tilt=Math.max(0,Math.min(.95,drag.tilt+(e.clientY-drag.y)*.003))});viewport.addEventListener('pointerup',()=>drag=null);viewport.addEventListener('pointercancel',()=>drag=null);viewport.addEventListener('wheel',e=>{e.preventDefault();zoom=Math.max(.65,Math.min(2.7,zoom*(e.deltaY>0?.92:1.08)))},{passive:false});viewport.addEventListener('keydown',e=>{if(e.target!==viewport)return;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')yaw-=.1;if(e.key==='ArrowRight')yaw+=.1;if(e.key==='ArrowUp')tilt=Math.min(.95,tilt+.1);if(e.key==='ArrowDown')tilt=Math.max(0,tilt-.1);if(e.key==='+')$('#plus').click();if(e.key==='-')$('#minus').click()});
}catch(err){console.error(err);$('#fallback').hidden=false;renderer?.domElement.remove();$('#pins').hidden=true;$('.map-help').hidden=true;$('.view-toggle').hidden=true;$('.map-controls').hidden=true;}
select(0);
